#include <stdio.h>
#include <string.h>
#include <stdlib.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        puts("USAGE");
        return 0;
    }
    const char *s1 = argv[1];
    const char *s2 = argv[2];
    size_t len1 = strlen(s1);
    size_t len2 = strlen(s2);
    if (len1 > 64 || len2 > 64) {
        puts("TOO_LONG");
        return 0;
    }
    // DP table of size (len1+1) x (len2+1)
    int dp[65][65]; // max 64+1
    for (size_t i = 0; i <= len1; ++i) dp[i][0] = (int)i;
    for (size_t j = 0; j <= len2; ++j) dp[0][j] = (int)j;
    for (size_t i = 1; i <= len1; ++i) {
        for (size_t j = 1; j <= len2; ++j) {
            if (s1[i-1] == s2[j-1]) {
                dp[i][j] = dp[i-1][j-1];
            } else {
                int del = dp[i-1][j];
                int ins = dp[i][j-1];
                int sub = dp[i-1][j-1];
                int mn = del < ins ? del : ins;
                if (sub < mn) mn = sub;
                dp[i][j] = mn + 1;
            }
        }
    }
    printf("%d\n", dp[len1][len2]);
    return 0;
}
